def summarize_inventory(items: list[dict[str, object]]) -> dict[str, int]:
    """Return total non-negative integer quantity for each SKU."""
    totals: dict[str, int] = {}
    for item in items:
        sku = str(item["sku"])
        quantity = item["quantity"]
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity < 0
            raise ValueError("quantity must be a non-negative integer")
        totals[sku] = quantity
    return dict(sorted(totals.items()))

from __future__ import annotations

import unittest

from catalog import summarize_inventory


class InventorySummaryTests(unittest.TestCase):
    def test_repeated_skus_are_accumulated(self) -> None:
        items = [
            {"sku": "B", "quantity": 2},
            {"sku": "A", "quantity": 1},
            {"sku": "B", "quantity": 3},
        ]
        self.assertEqual(summarize_inventory(items), {"A": 1, "B": 5})

    def test_zero_is_allowed(self) -> None:
        self.assertEqual(summarize_inventory([{"sku": "A", "quantity": 0}]), {"A": 0})

    def test_negative_quantity_is_rejected(self) -> None:
        with self.assertRaises(ValueError):
            summarize_inventory([{"sku": "A", "quantity": -1}])


if __name__ == "__main__":
    unittest.main()

